import sys

def isScramble(S1: str, S2: str) -> bool:
    n = len(S1)
    if n == 0:
        return True
    if n == 1:
        return S1 == S2

    # Memoization table: dp[i][j][k] means whether S1[i:i+k] and S2[j:j+k] are scrambles
    # We use a dictionary for sparse storage since many states might not be reached
    memo = {}

    def solve(s1_start, s2_start, length):
        if length == 1:
            return S1[s1_start] == S2[s2_start]

        key = (s1_start, s2_start, length)
        if key in memo:
            return memo[key]

        # Check character counts first for optimization
        count = [0] * 26
        for i in range(length):
            count[ord(S1[s1_start + i]) - ord('a')] += 1
            count[ord(S2[s2_start + i]) - ord('a')] -= 1

        for c in count:
            if c != 0:
                memo[key] = False
                return False

        # Try all possible split points
        for k in range(1, length):
            # Case 1: No swap
            # S1 splits into [s1_start, s1_start+k) and [s1_start+k, s1_start+length)
            # S2 splits into [s2_start, s2_start+k) and [s2_start+k, s2_start+length)
            if solve(s1_start, s2_start, k) and solve(s1_start + k, s2_start + k, length - k):
                memo[key] = True
                return True

            # Case 2: Swap
            # S1 splits into [s1_start, s1_start+length-k) and [s1_start+length-k, s1_start+length)
            # S2 splits into [start, start+k) and [start+k, start+length)
            # So we compare S1's first part with S2's second part (swapped)
            if solve(s1_start, s2_start + length - k, k) and solve(s1_start + k, s2_start, length - k):
                memo[key] = True
                return False

        memo[key] = False
        return False

    return solve(0, 0, n)

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return

    # Assuming the first line contains S1 and the second line contains S2
    # Or they might be on the same line separated by space.
    # Based on typical competitive programming formats, let's handle both.
    lines = [line.strip() for line in data if line.strip()]

    if len(lines) >= 2:
        s1 = lines[0]
        s2 = lines[1]
    elif len(lines) == 1:
        parts = lines[0].split()
        if len(parts) >= 2:
            s1 = parts[0]
            s2 = parts[1]
        else:
            return
    else:
        return

    if isScramble(s1, s2):
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    main()
